import json,numpy as np,matplotlib.pyplot as plt
x=json.load(open('reproduced_results.json')); a=np.array([v['ari'] for v in x['base']]); fig,ax=plt.subplots(figsize=(8,4)); ax.scatter(range(30),a,color='#52738c',s=30,label='K-Means runs'); ax.axhline(a.mean(),color='#555555',linestyle='--',label='K-Means mean'); ax.axhline(x['representative']['ari'],color='#bd7424',label='Representative'); ax.axhline(x['coassociation']['ari'],color='#23623c',label='Co-association'); ax.set(xlabel='Random seed',ylabel='Adjusted Rand index',title='External agreement across base and consensus partitions'); ax.legend(fontsize=8,ncol=2); fig.tight_layout(); fig.savefig('reproduced_ari.png',dpi=200)
